import { useParams } from 'react-router-dom'
import ProductsList from '../../components/ProductsList'
import starWars from '../../assets/images/star_wars.png'
import Pratos from '../../models/Pratos'
import Banner from '../../components/Banner'

// Dados do prato Star Wars
const pratoStarWars: Pratos = {
  id: 4,
  title: 'Star Wars',
  nota: 10,
  description:
    'Embarque em uma jornada intergaláctica com sabores exóticos e fascinantes. Uma experiência única com pratos que fazem referência ao universo Star Wars!',
  image: starWars,
  infos: ['Temática', 'Exótica']
}

const StarWars = () => {
  const { id } = useParams()

  return (
    <>
      <Banner />
      <h2>{pratoStarWars.title}</h2>
      <ProductsList
        pratos={[pratoStarWars]}
        title="Detalhes do Prato"
        background="gray"
      />
    </>
  )
}

export default StarWars
